//! Auto-generated Go code generation for Polyglot Lab.

use anyhow::Result;
use lab_node_sdk::GraphSpec;
use std::collections::{HashMap, HashSet};

/// Generates `go.mod` content.
pub fn generate_go_mod(project_name: &str) -> String {
    let module_name = crate::codegen::sanitize_ident(project_name);
    format!(
        r#"module {module_name}

go 1.22
"#
    )
}

/// Generates `nodes.go` with self-contained implementations of the required atomic nodes.
pub fn generate_nodes_go(used_kinds: &HashSet<&str>) -> String {
    let mut code = String::from(
        r#"// Code generated by Polyglot Lab. DO NOT EDIT.
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"
)

"#,
    );

    if used_kinds.contains("http_get") {
        code.push_str(
            r#"func httpGet(url string) (string, error) {
	fmt.Printf("   Fetching: %s\n", url)
	client := &http.Client{Timeout: 30 * time.Second}
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("User-Agent", "PolyglotLab-Export/0.4.0")
	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

"#,
        );
    }

    if used_kinds.contains("fs_read") {
        code.push_str(
            r#"func fsRead(path string) (string, error) {
	fmt.Printf("   Reading file: %s\n", path)
	content, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(content), nil
}

"#,
        );
    }

    if used_kinds.contains("fs_write") {
        code.push_str(
            r#"func fsWrite(path string, content string) (int, error) {
	fmt.Printf("   Writing to file: %s\n", path)
	err := os.WriteFile(path, []byte(content), 0644)
	if err != nil {
		return 0, err
	}
	return len(content), nil
}

"#,
        );
    }

    if used_kinds.contains("log_output") {
        code.push_str(
            r#"func logOutput(text any) error {
	fmt.Printf("   Log Output: %v\n", text)
	return nil
}

"#,
        );
    }

    if used_kinds.contains("json_parse") {
        code.push_str(
            r#"func selectPath(val any, path string) (any, error) {
	parts := strings.Split(strings.Trim(path, "."), ".")
	curr := val
	for _, part := range parts {
		if part == "" {
			continue
		}
		switch node := curr.(type) {
		case map[string]any:
			v, ok := node[part]
			if !ok {
				return nil, fmt.Errorf("key '%s' not found in path '%s'", part, path)
			}
			curr = v
		case []any:
			idx, err := strconv.Atoi(part)
			if err != nil || idx < 0 || idx >= len(node) {
				return nil, fmt.Errorf("invalid index '%s' in path '%s'", part, path)
			}
			curr = node[idx]
		default:
			return nil, fmt.Errorf("cannot navigate through non-container value at '%s'", part)
		}
	}
	return curr, nil
}

func jsonParse(raw string, path string) (any, error) {
	var parsed any
	if err := json.Unmarshal([]byte(raw), &parsed); err != nil {
		return nil, fmt.Errorf("invalid JSON: %w", err)
	}
	if path == "" {
		return parsed, nil
	}
	return selectPath(parsed, path)
}

"#,
        );
    }

    if used_kinds.contains("text_clean") {
        code.push_str(
            r#"func textClean(text string, trim, collapse, toLower, toUpper bool) (string, error) {
	if toLower && toUpper {
		return "", fmt.Errorf("'to_lower' and 'to_upper' cannot both be true")
	}
	result := text
	if trim {
		result = strings.TrimSpace(result)
	}
	if collapse {
		fields := strings.Fields(result)
		lead := !trim && len(result) > 0 && (result[0] == ' ' || result[0] == '\t' || result[0] == '\n')
		trail := !trim && len(result) > 0 && (result[len(result)-1] == ' ' || result[len(result)-1] == '\t' || result[len(result)-1] == '\n')
		core := strings.Join(fields, " ")
		prefix := ""
		suffix := ""
		if lead {
			prefix = " "
		}
		if trail && len(core) > 0 {
			suffix = " "
		}
		result = prefix + core + suffix
	}
	if toLower {
		result = strings.ToLower(result)
	}
	if toUpper {
		result = strings.ToUpper(result)
	}
	return result, nil
}

"#,
        );
    }

    if used_kinds.contains("delay") {
        code.push_str(
            r#"func delay(durationStr string) error {
	trimmed := strings.TrimSpace(durationStr)
	d, err := time.ParseDuration(trimmed)
	if err != nil {
		return fmt.Errorf("invalid duration format '%s': %w", trimmed, err)
	}
	fmt.Printf("   Sleeping for %v\n", d)
	time.Sleep(d)
	return nil
}

"#,
        );
    }

    if used_kinds.contains("string_to_path") {
        code.push_str(
            r#"func stringToPath(raw string) (string, error) {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" {
		return "", fmt.Errorf("path cannot be empty")
	}
	return trimmed, nil
}

"#,
        );
    }

    if used_kinds.contains("json_to_string") {
        code.push_str(
            r#"func jsonToString(val any) (string, error) {
	switch v := val.(type) {
	case string:
		return v, nil
	default:
		bytes, err := json.Marshal(v)
		if err != nil {
			return "", err
		}
		return string(bytes), nil
	}
}

"#,
        );
    }

    if used_kinds.contains("json_to_bool") {
        code.push_str(
            r#"func jsonToBool(val any) (bool, error) {
	switch v := val.(type) {
	case bool:
		return v, nil
	case string:
		return strconv.ParseBool(v)
	case float64:
		return v != 0, nil
	default:
		return false, fmt.Errorf("cannot convert %T to bool", val)
	}
}

"#,
        );
    }

    code
}

fn go_string_literal(value: &str) -> String {
    format!("{value:?}")
}

/// Generates Go code statement for a single node.
pub fn generate_go_node_call(
    node: &lab_node_sdk::NodeInstance,
    graph: &GraphSpec,
    indent: &str,
) -> String {
    let mut out = format!("{indent}// 🚀 Node: '{}' ({})\n", node.id, node.kind);
    let id_ident = crate::codegen::sanitize_ident(&node.id);

    let mut in_edges: HashMap<&str, (&str, &str)> = HashMap::new();
    for edge in &graph.edges {
        if edge.to.node == node.id {
            in_edges.insert(&edge.to.port, (&edge.from.node, &edge.from.port));
        }
    }

    match node.kind.as_str() {
        "http_get" => {
            let url_expr = if let Some(&(src, sport)) = in_edges.get("url") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let u = node.config.get("url").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(u)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_body, err := httpGet({url_expr})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed httpGet in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "fs_read" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let p = node.config.get("path").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_content, err := fsRead({path_expr})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed fsRead in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "fs_write" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let p = node.config.get("path").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(p)
            };
            let content_expr = if let Some(&(src, sport)) = in_edges.get("content") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let c = node.config.get("content").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(c)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_bytes_written, err := fsWrite({path_expr}, {content_expr})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed fsWrite in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "log_output" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let t = node.config.get("text").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(t)
            };
            out.push_str(&format!("{indent}logOutput({text_expr})\n"));
        }
        "json_parse" => {
            let json_expr = if let Some(&(src, sport)) = in_edges.get("json_str") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let j = node.config.get("json_str").and_then(|v| v.as_str()).unwrap_or("{}");
                go_string_literal(j)
            };
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let p = node.config.get("path").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_value, err := jsonParse({json_expr}, {path_expr})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed jsonParse in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "text_clean" => {
            let text_expr = if let Some(&(src, sport)) = in_edges.get("text") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let t = node.config.get("text").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(t)
            };
            let trim = node.config.get("trim").and_then(|v| v.as_bool()).unwrap_or(true);
            let collapse = node.config.get("collapse").and_then(|v| v.as_bool()).unwrap_or(false);
            let to_lower = node.config.get("to_lower").and_then(|v| v.as_bool()).unwrap_or(false);
            let to_upper = node.config.get("to_upper").and_then(|v| v.as_bool()).unwrap_or(false);
            out.push_str(&format!(
                "{indent}{id_ident}_cleaned, err := textClean({text_expr}, {trim}, {collapse}, {to_lower}, {to_upper})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed textClean in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "delay" => {
            let dur_expr = if let Some(&(src, sport)) = in_edges.get("duration") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let d = node.config.get("duration").and_then(|v| v.as_str()).unwrap_or("0ms");
                go_string_literal(d)
            };
            out.push_str(&format!(
                "{indent}if err := delay({dur_expr}); err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed delay in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "string_to_path" => {
            let path_expr = if let Some(&(src, sport)) = in_edges.get("path") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                let p = node.config.get("path").and_then(|v| v.as_str()).unwrap_or("");
                go_string_literal(p)
            };
            out.push_str(&format!(
                "{indent}{id_ident}_path, err := stringToPath({path_expr})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed stringToPath in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "json_to_string" => {
            let val_expr = if let Some(&(src, sport)) = in_edges.get("value") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                "\"\"".to_string()
            };
            out.push_str(&format!(
                "{indent}{id_ident}_text, err := jsonToString({val_expr})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed jsonToString in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        "json_to_bool" => {
            let val_expr = if let Some(&(src, sport)) = in_edges.get("value") {
                format!("{}_{}", crate::codegen::sanitize_ident(src), crate::codegen::sanitize_ident(sport))
            } else {
                "false".to_string()
            };
            out.push_str(&format!(
                "{indent}{id_ident}_value, err := jsonToBool({val_expr})\n\
                 {indent}if err != nil {{\n\
                 {indent}\tlog.Fatalf(\"Failed jsonToBool in {id_ident}: %v\", err)\n\
                 {indent}}}\n"
            ));
        }
        _ => {}
    }

    out
}

/// Generates `main.go` with topological execution and error handling.
pub fn generate_main_go(graph: &GraphSpec, topo_order: &[String]) -> Result<String> {
    let node_map: HashMap<&str, &lab_node_sdk::NodeInstance> =
        graph.nodes.iter().map(|n| (n.id.as_str(), n)).collect();

    let mut body = String::new();
    for id in topo_order {
        if let Some(node) = node_map.get(id.as_str()) {
            body.push_str(&generate_go_node_call(node, graph, "\t"));
        }
    }

    let code = format!(
        r#"// Code generated by Polyglot Lab. DO NOT EDIT.
package main

import (
	"fmt"
	"log"
)

func main() {{
	fmt.Println("🚀 Starting exported Go application...")

{body}
	fmt.Println("✅ Application finished successfully!")
}}
"#
    );

    Ok(code)
}
